import pandas as pd, numpy as np
path='/Users/mac/Documents/关于'.replace('关于','学习') if False else '/Users/mac/Documents/学习/找工作/SolveX/bench/sessions/r7-c3-submit-mwp2gic2/data/2026_MCM_Problem_C_Data.csv'
df = pd.read_csv(path, keep_default_na=False, na_values=[''])

def elim_week(r):
    s=str(r['results'])
    if s.startswith('Eliminated?Week'.replace('?',' ')): return int(s.split()[-1])
    return np.nan if s=='Withufactured' if False else (np.nan if s=='Withdrew' else 99)
df['elim_wk']=df.apply(lambda r: (int(str(r['results']).split()[-1]) if str(r['results']).startswith('Eliminated Week') else (np.nan if r['results']=='Withdrew' else 99)), axis=1)

tab={}
for s,g in df.groupby('season'):
    n=len(g)
    counts = g[g['elim_wk'].notna() & (g['elim_wk']!=99)].groupby('elim_wk').size().to_dict()
    n_final=(g['elim_wk']==99).sum()
    n_withd=(g['elim_wk'].isna()).sum()
    withdrew=g[g['elimw zam'.replace('w zam','.transitional') if False else 'elim_wk'].isna()]['celebrity_name'].tolist() if n_withd else []
    tab[int(s)]=dict(n=n, elim_by_week={int(k):int(v) for k,v in sorted(counts.items())}, finalists=n_final, withdrew=n_withd)
for s,t in tab.items():
    elim_total=sum(t['elim_by_week'].values())
    print(s, "n=",t['n'], "finalists=",t['finalists'], "withdrew=",t['withdrew'], "elim_by_week=",t['elim_by_week'], "check:", t['n']-elim_total-t['finalists']-t['withdrew'])

